nextflow_process {

    name "Test Process BWAFASTALIGN_INDEX"
    script "../main.nf"
    process "BWAFASTALIGN_INDEX"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "bwafastalign"
    tag "bwafastalign/index"

    test("BWAFASTALIGN index") {

        when {
            process {
                """
                input[0] = [
                    [id: 'test'],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                // genome.fasta.kmer is a fixed-size ~4.8 GB hash table — snapshot by name only, MD5 all others
                { assert snapshot(
                    new File(process.out.index[0][1].toString()).listFiles()
                        .sort { it.name }
                        .collect { f -> f.name.endsWith('.kmer') ? f.name : file(f.absolutePath) },
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

    test("BWAFASTALIGN index - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [id: 'test'],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(process.out).match() }
            )
        }

    }

}
